// chromly calibration repro — regress-567177599 (turbolev loop peeling phi type)
// Nguồn: test/mjsunit/turbolev/regress-567177599.js @ fix 41d0351e57 (fix sau checkout b8ffaab → bug có trong build hiện tại)
// Chạy: d8 --allow-natives-syntax --turbolev --abort-on-uncaught-exception repro.js

function assertEquals(a, b) {
  if (a !== b) throw new Error("assertEquals failed: expected " + b + " got " + a);
}
function assertFalse(x) {
  if (x) throw new Error("assertFalse failed");
}

var loop_value = 1.2;
var exit_value = 2.5;
loop_value = 1.4;
exit_value = 1.5;

const box = {value: 1.2};
const input = {[Symbol.toPrimitive]() { return box.value; }};

function store(n, input) {
  let value = 1.1;
  let sum = 0;
  while (n-- > 0) {
    sum += value;
    value = +input;
    loop_value = value;
  }
  exit_value = value;
  return sum;
}

%PrepareFunctionForOptimization(store);
store(3, input);

%OptimizeFunctionOnNextCall(store);
store(3, input);

box.value = 42;
store(3, input);
assertEquals(42, exit_value);
assertFalse(%IsSmi(exit_value));
print("REPRO-PASS");
